import { useCallback, useEffect, useState } from 'react';
import { useMediaQuery } from 'usehooks-ts';

export type TTheme = 'light' | 'dark';
export type TThemeClass = 'dark-theme' | 'light-theme' | 'system-theme';

const THEME_CLASSES = ['dark-theme', 'light-theme', 'system-theme'] as const;

/**
 * Returns the currently resolved Foundation theme.
 *
 * Explicit themes on `<body>` take precedence over themes on `<html>`. A
 * `system-theme` class (or no explicit theme class) resolves using the user's
 * `prefers-color-scheme` setting. The returned value updates when either the
 * document theme classes or the system color scheme changes. The initial
 * value is `light` so server and client rendering produce the same output;
 * the effective client theme is resolved after mounting.
 */
export default function useCurrentTheme(): TTheme {
  const prefersDark = useMediaQuery('(prefers-color-scheme: dark)', {
    defaultValue: false,
    initializeWithValue: false
  });

  const detectTheme = useCallback((): TTheme => {
    if (typeof document !== 'undefined') {
      const themeElement = [document.body, document.documentElement].find(element =>
        THEME_CLASSES.some(themeClass => element.classList.contains(themeClass))
      );

      if (themeElement?.classList.contains('dark-theme')) return 'dark';
      if (themeElement?.classList.contains('light-theme')) return 'light';
    }

    return prefersDark ? 'dark' : 'light';
  }, [prefersDark]);

  const [currentTheme, setCurrentTheme] = useState<TTheme>('light');

  useEffect(() => {
    setCurrentTheme(detectTheme());

    if (typeof document === 'undefined' || typeof MutationObserver === 'undefined') {
      return undefined;
    }

    const observer = new MutationObserver(() => {
      setCurrentTheme(detectTheme());
    });
    const options: MutationObserverInit = { attributes: true, attributeFilter: ['class'] };

    observer.observe(document.documentElement, options);
    observer.observe(document.body, options);

    return () => {
      observer.disconnect();
    };
  }, [detectTheme]);

  return currentTheme;
}
